```bash
# File: rebase-onto-main.sh — update a LOCAL feature branch for linear history.

# Feature branch cut 3 days ago; main has advanced since.
git checkout feature/monthly-statement

# Bring in the latest main commits.
git fetch origin

# REBASE: replay MY commits on top of the latest main.
# Old commits are abandoned; NEW commits with new hashes are created.
git rebase origin/main
# If a conflict arises, Git pauses. Fix the file, then:
#   git add <file>
#   git rebase --continue
# To bail out entirely and restore the pre-rebase state:
#   git rebase --abort

# Because the branch diverged from its old remote state, push with LEASE
# (safe: refuses to overwrite if someone else pushed since my last fetch).
git push --force-with-lease origin feature/monthly-statement
```

```bash
# File: interactive-cleanup.sh — squash messy local commits BEFORE sharing.

# Suppose the last 5 commits are: "wip", "more", "fix typo", "oops", "done".
git log --oneline -5
#   e5f6a7b done
#   d4c3b2a oops
#   c3b2a19 fix typo
#   b2a1908 more
#   a190876 wip

# Interactive rebase over the last 5 commits.
git rebase -i HEAD~5
# In the editor: keep the first as 'pick', mark the rest 'squash' (or 'fixup'),
# then write ONE clean message:
#   pick a190876 STMT-55 generate monthly PDF statement for an account
#   squash b2a1908
#   squash c3b2a19
#   squash d4c3b2a
#   squash e5f6a7b

# Result: ONE tidy commit. Safe because these commits were never pushed.
git log --oneline -1
#   f00dcafe STMT-55 generate monthly PDF statement for an account
```

```bash
# File: DANGER-shared-rebase.sh — what NOT to do (illustration only).

# A teammate has ALREADY pulled feature/monthly-statement and built on it.
# If I rebase it and force-push, their history points at commits that no
# longer exist on the remote:
#   git rebase origin/main
#   git push --force origin feature/monthly-statement   # <-- DANGEROUS
# Teammate's next pull sees divergent history, confusing conflicts, and a
# careless --force can OVERWRITE commits they pushed -> lost work.
#
# RULE: never rebase shared/public history. Rebase only unshared branches.
```

