// ─── File: src/main/java/com/bank/statements/StatementGenerator.java ───
package com.bank.statements;

import java.math.BigDecimal;
import java.time.YearMonth;

// The feature being built across the commits we rebase and squash.
public class StatementGenerator {

    // Produce a one-line monthly statement summary for an account.
    public String monthlySummary(String accountId, YearMonth month,
                                 BigDecimal opening, BigDecimal closing) {
        BigDecimal netChange = closing.subtract(opening);
        return String.format("Statement %s for %s: opening=%s closing=%s net=%s",
                month, accountId, opening, closing, netChange);
    }
}
