package com.bank.statements;

import org.junit.jupiter.api.Test;
import java.math.BigDecimal;
import java.time.YearMonth;
import static org.junit.jupiter.api.Assertions.*;

class StatementGeneratorTest {

    @Test
    void summaryShowsNetChange() {
        StatementGenerator gen = new StatementGenerator();
        // Rajesh SAV2001: opened at 1,000,000, closed at 950,000 -> net -50000
        String out = gen.monthlySummary("SAV2001", YearMonth.of(2026, 10),
                new BigDecimal("1000000"), new BigDecimal("950000"));
        assertTrue(out.contains("net=-50000"));
    }
}
